mapper.select:
SELECT 
FROM ddc_si_reference ref
LEFT JOIN ddc_si_resource sr ON sr.tenant_id = ref.tenant_id AND sr.id = ref.source_resource_id
WHERE ref.tenant_id = #{tenantId}
  AND ref.env_code = #{envCode}
  AND ref.target_kind = #{targetKind}
  AND ref.target_key = #{targetKey}
  AND ref.deleted_at IS NULL
  AND (
      ref.source_type = 'TIANJI_PROCESS'
      OR (sr.id IS NOT NULL AND sr.deleted_at IS NULL AND sr.lifecycle_status <> 'ARCHIVED')
  )
ORDER BY ref.source_type ASC, ref.source_key ASC

SELECT 
FROM ddc_si_reference ref
WHERE ref.tenant_id = #{tenantId}
  AND ref.env_code = #{envCode}
  AND ref.source_type = #{sourceType}
  AND ref.source_key = #{sourceKey}
  AND ref.deleted_at IS NULL
ORDER BY ref.target_kind ASC, ref.target_key ASC

mapper.update:
UPDATE ddc_si_reference
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
    version = version + 1,
    update_user_id = #{updateUserId},
    update_time = #{updateTime}
WHERE tenant_id = #{tenantId}
  AND env_code = #{envCode}
  AND source_type = #{sourceType}
  AND source_key = #{sourceKey}
  AND deleted_at IS NULL

UPDATE ddc_si_reference
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
    version = version + 1,
    update_user_id = #{updateUserId},
    update_time = #{updateTime}
WHERE tenant_id = #{tenantId}
  AND env_code = #{envCode}
  AND source_type = 'TIANJI_PROCESS'
  AND source_key = #{processKey}
  AND deleted_at IS NULL
